do $guided_study_v16_2_content_seed$
declare
  content jsonb := '{"packVersion":"TECESCOLA_BNCC_GUIDED_STUDY_EM1_V16_2","contentVersion":7,"officialSourceUrl":"https://basenacionalcomum.mec.gov.br/images/historico/BNCC_EnsinoMedio_embaixa_site_110518.pdf","recommendedGrade":1,"recommendedGradeSource":"TECESCOLA_PEDAGOGICAL_SEQUENCE","authoringAudit":{"sourcePack":"TECESCOLA_BNCC_GUIDED_STUDY_V13","reviewType":"TECHNICAL_CONTENT_EXTENSION","humanCertification":"NOT_CLAIMED","sourceRecordsMutated":false,"reviewCriteria":["Check each BNCC code, description, component, area, and printed source page against the official 2018 document.","Check every calculation, unit, model domain, distractor, answer key, and explanation independently.","Check that the assessment purpose and cognitive demand fit the skill and 1st-year institutional sequence.","Keep content versioned separately and preserve all earlier questions, lessons, sessions, and evidence.","Do not represent technical validation as human pedagogical certification."]},"skills":[{"code":"EM13MAT302","componentCode":"MAT","area":"MATEMATICA","domain":"MODELOS_POLINOMIAIS","officialPage":536,"title":"Construir modelos com funções polinomiais","officialDescription":"Construir modelos empregando as funções polinomiais de 1º ou 2º graus, para resolver problemas em contextos diversos, com ou sem apoio de tecnologias digitais.","sequenceAfter":"EM13MAT101","lesson":{"title":"Modelar situações com funções de 1º e 2º graus","summary":"Um modelo polinomial relaciona grandezas por uma taxa constante ou variável; construir o modelo exige identificar dados, domínio e limites do contexto.","content":"## Da situação ao modelo\n\nConstruir um modelo começa pela escolha das grandezas e de suas unidades. Defina qual variável é independente, qual depende dela e quais valores fazem sentido no contexto. Uma função polinomial não é apenas uma expressão: ela representa uma relação que precisa ser confrontada com dados e com as condições do problema.\n\n## Modelos de 1º grau\n\nUma função de 1º grau pode ser escrita como f(x) = ax + b. O coeficiente a representa a taxa de variação constante entre as grandezas, e b é o valor inicial quando x = 0, se esse valor pertencer ao domínio do modelo. Por exemplo, uma cobrança com parcela fixa e custo por unidade pode ser representada por C(n) = b + an. Verifique as unidades: se a está em reais por unidade, an está em reais.\n\nCom dois pontos de uma relação linear, a taxa é a = (y2 - y1)/(x2 - x1). Depois, substitua um ponto para obter b. Dados adicionais permitem avaliar se a hipótese linear é razoável; dois pontos, sozinhos, sempre determinam uma reta, mas não provam que o fenômeno real seja linear.\n\n## Modelos de 2º grau\n\nUma função quadrática tem a forma f(x) = ax² + bx + c, com a diferente de zero. A taxa de variação não é constante. O sinal de a indica se a parábola abre para cima ou para baixo; o vértice pode representar um mínimo ou máximo, desde que esteja no domínio considerado. As raízes indicam onde o modelo vale zero, mas só têm interpretação quando esses valores são possíveis na situação.\n\nUm retângulo de perímetro 24 m pode ter lados x e 12 - x. Sua área é A(x) = x(12 - x) = 12x - x², com 0 < x < 12. O vértice ocorre em x = 6 m e fornece a área máxima de 36 m². Não se deve usar a fórmula fora do intervalo físico dos lados.\n\n## Avaliar e comunicar\n\nCompare previsões com os dados disponíveis, explicite hipóteses e restrinja conclusões ao domínio sustentado. Uma boa solução informa o significado e a unidade dos coeficientes, mostra por que o modelo escolhido é adequado e reconhece quando a realidade pode deixar de seguir a expressão.","workedExample":"Uma oficina cobra R$ 12 de taxa fixa e R$ 4 por peça. Para n peças, C(n) = 12 + 4n reais; com 7 peças, C(7) = R$ 40. Em outro problema, um retângulo com perímetro de 24 m tem lados x e 12 - x; A(x) = 12x - x² atinge 36 m² em x = 6 m, dentro do domínio 0 < x < 12.","tips":["Declare as variáveis, suas unidades e o intervalo possível antes de escolher uma função.","Em ax + b, interprete a como taxa constante e b como valor inicial apenas quando x = 0 fizer sentido.","Em uma parábola, verifique se o vértice e as raízes pertencem ao domínio real do problema.","Confira o modelo em dados conhecidos e não extrapole sem justificar as hipóteses."],"estimatedMinutes":14},"questions":[{"id":"mat302-probe-01","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"TARIFA_FIXA_E_VARIAVEL","statement":"Um serviço cobra R$ 8 de taxa fixa e mais R$ 3 por quilômetro. Qual função representa o preço C para x quilômetros?","options":["C(x) = 8 + 3x","C(x) = 3 + 8x","C(x) = 11x","C(x) = 8x - 3"],"answer":"C(x) = 8 + 3x","explanation":"A taxa fixa é o valor inicial 8 e cada quilômetro acrescenta 3; por isso o custo é 8 + 3x reais."},{"id":"mat302-probe-02","purpose":"PROBE","difficulty":"MEDIUM","cognitiveProcess":"ANALYZE","contextFamily":"DIFERENCAS_SUCESSIVAS","statement":"Uma sequência de valores é 2, 5, 10, 17 para x = 0, 1, 2, 3. Qual expressão quadrática reproduz os quatro valores?","options":["x² + 2x + 2","2x + 2","x² + 5","2x² + 1"],"answer":"x² + 2x + 2","explanation":"Substituindo x = 0, 1, 2 e 3 em x² + 2x + 2, obtemos 2, 5, 10 e 17; as diferenças crescem de duas em duas."},{"id":"mat302-practice-01","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"MODEL","contextFamily":"AJUSTE_LINEAR_POR_DOIS_PONTOS","statement":"Uma gráfica cobra R$ 18 por 2 cartazes e R$ 30 por 5 cartazes, mantendo a mesma taxa por cartaz. Qual função linear descreve o custo C(n)?","options":["C(n) = 4n + 10","C(n) = 6n + 6","C(n) = 10n + 4","C(n) = 4n + 18"],"answer":"C(n) = 4n + 10","explanation":"A taxa é (30 - 18)/(5 - 2) = 4 reais por cartaz. Usando o ponto (2,18), o valor inicial é 18 - 4·2 = 10."},{"id":"mat302-practice-02","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"FORMULATE","contextFamily":"AREA_COM_PERIMETRO_FIXO","statement":"Um canteiro retangular terá perímetro de 30 m. Se um lado mede x metros, qual função representa a área A(x)?","options":["A(x) = 15x - x²","A(x) = 30x - x²","A(x) = 15x + x²","A(x) = 30 - 2x"],"answer":"A(x) = 15x - x²","explanation":"Como 2(x + y) = 30, o outro lado é y = 15 - x. Logo A(x) = x(15 - x) = 15x - x², com 0 < x < 15."},{"id":"mat302-transfer-01","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"APPLY","contextFamily":"ORCAMENTO_DE_PRODUCAO","statement":"Uma associação tem R$ 50 para pagar uma taxa de R$ 20 e depois R$ 3 por kit produzido. Qual é o maior número inteiro de kits que cabe no orçamento?","options":["10 kits","9 kits","11 kits","16 kits"],"answer":"10 kits","explanation":"O custo é C(n) = 20 + 3n. A condição 20 + 3n ≤ 50 implica n ≤ 10; 10 kits custam exatamente R$ 50."},{"id":"mat302-transfer-02","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"INTERPRET","contextFamily":"ALTURA_E_TEMPO","statement":"Em um modelo ideal, a altura de um objeto é h(t) = -5t² + 20t + 1 metros, para 0 ≤ t ≤ 4 segundos. Em que instante o modelo prevê a altura máxima?","options":["2 segundos","1 segundo","4 segundos","20 segundos"],"answer":"2 segundos","explanation":"O vértice tem t = -b/(2a) = -20/(2·-5) = 2 s. Como a parábola abre para baixo e 2 pertence ao intervalo, esse é o instante de altura máxima."},{"id":"mat302-lock-01","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"VERTICE_E_RESTRICAO","statement":"A área de uma peça é A(x) = -2x² + 16x + 3 cm², e o processo só permite 0 ≤ x ≤ 5 cm. Qual valor de x maximiza a área no domínio permitido?","options":["4 cm","5 cm","8 cm","0 cm"],"answer":"4 cm","explanation":"O vértice ocorre em x = -16/(2·-2) = 4 cm, que está no intervalo permitido; como a parábola abre para baixo, esse ponto é o máximo."},{"id":"mat302-lock-02","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"COMPARE","contextFamily":"CRESCIMENTO_E_MODELO","statement":"Uma tabela mostra aumentos de 3 unidades a cada passo. Qual evidência adicional apoiaria melhor o uso de um modelo linear, em vez de concluir apenas pela primeira diferença?","options":["Verificar em vários dados se as diferenças continuam constantes no domínio e se a taxa tem sentido no contexto","Observar somente que o primeiro valor é positivo","Escolher a reta porque qualquer sequência pode ser aproximada por uma linha","Ignorar as unidades das grandezas"],"answer":"Verificar em vários dados se as diferenças continuam constantes no domínio e se a taxa tem sentido no contexto","explanation":"Uma taxa constante é compatível com um modelo linear, mas a escolha também precisa ser testada em outros dados e respeitar o significado e o domínio das variáveis."},{"id":"mat302-review-01","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"DISTINGUISH","contextFamily":"LIMITES_DE_EXTRAPOLACAO","statement":"Uma equipe ajustou uma função de 2º grau a medições entre x = 1 e x = 6. O que é mais responsável ao prever o resultado para x = 40?","options":["Reconhecer que a extrapolação está fora do intervalo observado e validar novas hipóteses e dados","Aceitar a previsão porque toda parábola continua representando o fenômeno","Tratar o resultado como certo se a curva passar pelos dados iniciais","Apagar o domínio para permitir qualquer valor de x"],"answer":"Reconhecer que a extrapolação está fora do intervalo observado e validar novas hipóteses e dados","explanation":"O ajuste descreve os dados e hipóteses no intervalo conhecido; para x = 40, o comportamento pode mudar e precisa ser verificado antes de concluir."},{"id":"mat302-review-02","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"SELECT","contextFamily":"ESCOLHA_DE_MODELO","statement":"Uma relação apresenta taxa média que aumenta quando x cresce e os dados ficam próximos de uma parábola. Qual conclusão é melhor?","options":["Um modelo de 2º grau pode ser investigado, mas deve ser confrontado com dados, domínio e contexto","A taxa crescente prova que qualquer função quadrática será correta","Um modelo linear é obrigatório porque relaciona duas grandezas","O gráfico, sozinho, identifica a causa física da variação"],"answer":"Um modelo de 2º grau pode ser investigado, mas deve ser confrontado com dados, domínio e contexto","explanation":"A variação da taxa pode motivar um modelo quadrático, mas adequação depende de dados, intervalo e interpretação, não apenas da forma visual."}]},{"code":"EM13CNT204","componentCode":"CNT","area":"CIENCIAS_DA_NATUREZA","domain":"GRAVITACAO_E_MOVIMENTO","officialPage":543,"title":"Explicar movimentos por interações gravitacionais","officialDescription":"Elaborar explicações e previsões a respeito dos movimentos de objetos na Terra, no Sistema Solar e no Universo com base na análise das interações gravitacionais.","sequenceAfter":"EM13CNT101","lesson":{"title":"Prever movimentos por gravitação","summary":"A gravitação é uma interação atrativa entre massas; relacionar força, distância e velocidade permite explicar quedas e órbitas com hipóteses explícitas.","content":"## A interação gravitacional\n\nTodo par de corpos com massa se atrai gravitacionalmente. Para dois corpos de massas m1 e m2 separados por uma distância r entre seus centros, o módulo da força é F = G·m1·m2/r², em que G é a constante gravitacional. A força aumenta quando uma das massas aumenta e diminui com o quadrado da distância: mantendo as massas, ao dobrar r a força passa a um quarto; ao triplicar r, passa a um nono.\n\nA força que um planeta exerce sobre um objeto depende da massa do objeto, mas o campo gravitacional do planeta em certo ponto não depende da massa usada para medi-lo. Perto da superfície terrestre e desprezando o ar, objetos em queda livre têm a mesma aceleração gravitacional. Diferenças observadas em uma sala podem resultar da resistência do ar, não de uma regra de que corpos mais pesados sempre caem mais rápido. Massa mede inércia; peso é a força gravitacional sobre o corpo.\n\n## Quedas e órbitas\n\nUma órbita não significa ausência de gravidade. Um satélite tem velocidade lateral enquanto a gravidade o acelera em direção ao corpo central. Essa aceleração muda continuamente a direção da velocidade, produzindo uma trajetória curva. Se a gravidade deixasse de atuar, o movimento seguiria aproximadamente em linha tangente, de acordo com a velocidade instantânea. A distância, isoladamente, não determina a trajetória: também importam velocidade e direção iniciais.\n\nPara previsões simples, podem-se adotar modelos como dois corpos, órbita aproximadamente circular e ausência de propulsão ou perturbações relevantes. O modelo permite comparar tendências, mas deve declarar suas hipóteses. Em sistemas reais, outros corpos, variações de massa, atmosfera e manobras podem modificar o movimento previsto.\n\n## Construir uma explicação\n\nIdentifique os corpos que interagem, a distância entre seus centros e o movimento observado. Separe força gravitacional, campo e aceleração; depois aplique a relação adequada às condições do problema. Uma explicação verificável informa o que foi mantido constante, qual mudança foi prevista e quais limitações podem alterar o resultado.","workedExample":"Mantendo as massas de dois corpos, se a distância entre seus centros passa de r para 2r, F2/F1 = r²/(2r)² = 1/4. A força gravitacional fica quatro vezes menor. Essa comparação não determina sozinha a órbita, pois também é preciso conhecer a velocidade e a direção do movimento.","tips":["Na relação gravitacional, indique se as massas ou a distância estão mudando e mantenha as demais grandezas fixas.","Ao comparar distâncias, lembre que a força varia com 1/r², não com 1/r.","Não confunda massa do objeto, força peso e campo gravitacional.","Para explicar uma órbita, considere gravidade e velocidade inicial; não diga que o satélite está fora da gravidade."],"estimatedMinutes":14},"questions":[{"id":"cnt204-probe-01","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"PREDICT","contextFamily":"LEI_DO_INVERSO_DO_QUADRADO","statement":"Mantendo as massas de dois corpos, a distância entre seus centros dobra. Como muda a força gravitacional entre eles?","options":["Fica quatro vezes menor","Fica duas vezes menor","Fica duas vezes maior","Permanece igual"],"answer":"Fica quatro vezes menor","explanation":"A força é inversamente proporcional ao quadrado da distância. Substituir r por 2r divide a força por (2r)²/r² = 4."},{"id":"cnt204-probe-02","purpose":"PROBE","difficulty":"MEDIUM","cognitiveProcess":"INTERPRET","contextFamily":"QUEDA_LIVRE_E_AR","statement":"Em uma câmara sem ar, uma esfera de metal e uma de madeira são soltas da mesma altura. Desprezando outras interações, o que se prevê perto da Terra?","options":["As duas têm a mesma aceleração gravitacional","A esfera de metal tem necessariamente o dobro da aceleração","A esfera de madeira não sofre gravidade","A mais pesada chega primeiro porque tem maior massa"],"answer":"As duas têm a mesma aceleração gravitacional","explanation":"Sem resistência do ar, a aceleração de queda perto da Terra é a mesma para os dois corpos; a massa altera a força gravitacional, mas também a inércia."},{"id":"cnt204-practice-01","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"APPLY","contextFamily":"MASSA_DO_CORPO_EM_ORBITA","statement":"Uma sonda de massa dobrada fica à mesma distância de um planeta. Mantendo a massa do planeta, o que acontece com a força gravitacional sobre a sonda?","options":["Dobra","Cai à metade","Fica quatro vezes menor","Não muda"],"answer":"Dobra","explanation":"A força é proporcional ao produto das massas. Se apenas a massa da sonda dobra, a força gravitacional sobre ela também dobra."},{"id":"cnt204-practice-02","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"EXPLAIN","contextFamily":"VELOCIDADE_TANGENCIAL","statement":"Por que um satélite em órbita aproximadamente circular não segue em linha reta?","options":["A gravidade fornece aceleração em direção ao planeta e muda continuamente a direção da velocidade","A gravidade deixa de atuar quando o satélite alcança certa altitude","O satélite permanece parado e o planeta gira ao redor dele","A atmosfera empurra o satélite para o centro em qualquer altitude"],"answer":"A gravidade fornece aceleração em direção ao planeta e muda continuamente a direção da velocidade","explanation":"A velocidade lateral tenderia a manter o movimento tangente; a atração gravitacional curva a trajetória ao produzir aceleração para o corpo central."},{"id":"cnt204-transfer-01","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"ANALYZE","contextFamily":"ORBITA_LUNAR","statement":"A Lua permanece em órbita ao redor da Terra. Qual explicação relaciona melhor a gravidade ao movimento observado?","options":["A gravidade terrestre produz aceleração para a Terra enquanto a velocidade da Lua mantém componente lateral","A Lua está tão distante que nenhuma gravidade atua sobre ela","A gravidade cancela toda a velocidade da Lua e a mantém imóvel","A Lua é sustentada por uma força de contato com o espaço"],"answer":"A gravidade terrestre produz aceleração para a Terra enquanto a velocidade da Lua mantém componente lateral","explanation":"A combinação entre a velocidade lateral e a aceleração gravitacional curva continuamente o movimento, formando uma órbita em vez de uma queda vertical simples."},{"id":"cnt204-transfer-02","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"PREDICT","contextFamily":"COMPARACAO_DE_DISTANCIAS","statement":"Dois objetos de teste estão à distância r e 3r do mesmo planeta, com massas de teste iguais. Comparando o campo gravitacional do planeta nesses pontos, qual relação é prevista pelo modelo?","options":["O campo em 3r é um nono do campo em r","O campo em 3r é um terço do campo em r","O campo em 3r é três vezes maior","O campo é igual porque as massas de teste são iguais"],"answer":"O campo em 3r é um nono do campo em r","explanation":"O campo gravitacional de uma massa central varia com 1/r². Ao triplicar a distância, o valor fica dividido por 3² = 9; a massa de teste não altera o campo."},{"id":"cnt204-lock-01","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"DISTINGUISH","contextFamily":"CAMPO_E_FORCA","statement":"Um planeta tem campo gravitacional g em determinado ponto. Se um instrumento de medição for substituído por outro corpo de massa duas vezes maior no mesmo ponto, o que se espera?","options":["O campo continua g, mas a força gravitacional sobre o corpo dobra","O campo dobra e a força permanece igual","O campo cai à metade e a força dobra","Campo e força permanecem iguais"],"answer":"O campo continua g, mas a força gravitacional sobre o corpo dobra","explanation":"O campo é determinado pela massa do planeta e pela posição. A força sobre o corpo é F = m·g, então dobrar a massa de teste dobra a força, sem alterar o campo."},{"id":"cnt204-lock-02","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"HIPOTESES_DE_ORBITA","statement":"Uma equipe prevê a trajetória de um satélite supondo apenas a gravidade de um planeta. Qual informação é indispensável para avaliar a previsão?","options":["A posição, a velocidade e a direção iniciais, além dos limites do modelo de dois corpos","Somente a cor externa do satélite","A altitude, sem conhecer qualquer velocidade","A massa do satélite, porque ela sozinha determina toda a trajetória"],"answer":"A posição, a velocidade e a direção iniciais, além dos limites do modelo de dois corpos","explanation":"A trajetória depende das condições iniciais e da interação considerada. Perturbações e propulsão também podem limitar a previsão simplificada."},{"id":"cnt204-review-01","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"INTERPRET","contextFamily":"MOVIMENTO_TANGENCIAL","statement":"Se a atração gravitacional sobre um satélite desaparecesse instantaneamente, qual seria a tendência imediata do movimento idealizado?","options":["Seguir aproximadamente em linha reta na direção tangente à órbita","Parar imediatamente no ponto em que estava","Cair radialmente em direção ao planeta","Continuar na mesma órbita circular sem alteração"],"answer":"Seguir aproximadamente em linha reta na direção tangente à órbita","explanation":"Sem a aceleração gravitacional para curvar o movimento, a velocidade instantânea aponta ao longo da tangente e tende a manter direção e módulo."},{"id":"cnt204-review-02","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"SYNTHESIZE","contextFamily":"PREVISAO_E_LIMITES","statement":"Um modelo de dois corpos prevê a trajetória de um planeta ao redor de uma estrela, mas observações acumulam pequenos desvios. Qual ação científica é mais adequada?","options":["Verificar medições e hipóteses, incluindo a influência de outros corpos, antes de revisar o modelo","Descartar todas as observações porque o modelo inicial é exato","Concluir que a gravidade não existe","Alterar os dados para que coincidam com a previsão"],"answer":"Verificar medições e hipóteses, incluindo a influência de outros corpos, antes de revisar o modelo","explanation":"Desvios podem indicar perturbações, limites de medição ou hipóteses incompletas. A revisão deve confrontar explicações com novas evidências."}]}]}'::jsonb;
  skill_data jsonb;
  lesson_data jsonb;
  question_data jsonb;
  v_catalog_id uuid;
  v_skill_id uuid;
  v_question_id uuid;
  v_question_set_id uuid;
  content_id text;
  next_position integer;
  validation jsonb;
begin
  select catalog.id into v_catalog_id from public.learning_curriculum_catalogs catalog
   where catalog.code = 'BNCC_2018' and catalog.active order by catalog.version desc limit 1;
  if v_catalog_id is null then raise exception 'GUIDED_STUDY_V16_2_BNCC_CATALOG_MISSING'; end if;

  for skill_data in select value from jsonb_array_elements(content->'skills') loop
    insert into public.learning_curriculum_skills(
      catalog_id, code, stage, grade_level, subject_area, domain, title, description,
      active, node_kind, content_readiness, mastery_targetable, pedagogical_review_status,
      bncc_alignment_status, publication_status, metadata
    ) values (
      v_catalog_id, skill_data->>'code', 'ENSINO_MEDIO', null, skill_data->>'area', skill_data->>'domain',
      skill_data->>'title', skill_data->>'officialDescription', true, 'LEAF', 'CONTENT_READY', false,
      'PEDAGOGICAL_REVIEW_PENDING', 'CANDIDATE', 'STAGING',
      jsonb_build_object(
        'official_code', skill_data->>'code', 'official_source_id', 'BNCC_EM_2018',
        'official_source_url', content->>'officialSourceUrl',
        'official_source_page', (skill_data->>'officialPage')::integer,
        'official_component_code', skill_data->>'componentCode', 'official_stage', 'ENSINO_MEDIO',
        'official_grade_range', '1-3', 'mapping_status', 'MAPPED',
        'mapping_source', 'TECESCOLA_BNCC_GUIDED_STUDY_V16_2',
        'content_pack', content->>'packVersion', 'content_version', (content->>'contentVersion')::integer,
        'recommended_grade', (content->>'recommendedGrade')::integer,
        'recommended_grade_source', content->>'recommendedGradeSource',
        'sequence_after', skill_data->>'sequenceAfter',
        'pedagogical_review_status', 'PENDING'
      )
    ) on conflict (catalog_id, code) do nothing;

    select skill.id into v_skill_id from public.learning_curriculum_skills skill
     where skill.catalog_id = v_catalog_id and skill.code = skill_data->>'code';
    if v_skill_id is null then raise exception 'GUIDED_STUDY_V16_2_SKILL_NOT_FOUND code=%', skill_data->>'code'; end if;
    if (select coalesce(skill.metadata->>'official_code', skill.code) from public.learning_curriculum_skills skill where skill.id = v_skill_id)
       is distinct from skill_data->>'code' then
      raise exception 'GUIDED_STUDY_V16_2_OFFICIAL_CODE_MISMATCH code=%', skill_data->>'code';
    end if;

    insert into public.learning_curriculum_grade_targets(
      catalog_id, stage, grade_level, subject_area, canonical_skill_id, priority, sort_order, active
    ) values (
      v_catalog_id, 'ENSINO_MEDIO', (content->>'recommendedGrade')::smallint,
      skill_data->>'area', v_skill_id, 10, (skill_data->>'officialPage')::integer, true
    ) on conflict (catalog_id, stage, grade_level, subject_area, canonical_skill_id)
    do update set active = true, priority = excluded.priority, sort_order = excluded.sort_order, updated_at = now();

    lesson_data := skill_data->'lesson';
    insert into public.learning_skill_lessons(
      canonical_skill_id, version, title, summary, content_markdown, worked_example, tips,
      estimated_minutes, active, metadata
    ) values (
      v_skill_id, (content->>'contentVersion')::integer, lesson_data->>'title', lesson_data->>'summary',
      lesson_data->>'content', lesson_data->>'workedExample',
      array(select jsonb_array_elements_text(lesson_data->'tips')),
      (lesson_data->>'estimatedMinutes')::integer, true,
      jsonb_build_object('content_pack', content->>'packVersion', 'content_version', (content->>'contentVersion')::integer,
        'official_bncc_code', skill_data->>'code', 'official_source_url', content->>'officialSourceUrl',
        'official_source_page', (skill_data->>'officialPage')::integer, 'content_origin', 'AUTHORED_V16_2',
        'sequence_after', skill_data->>'sequenceAfter', 'recommended_grade', (content->>'recommendedGrade')::integer,
        'recommended_grade_source', content->>'recommendedGradeSource',
        'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING')
    ) on conflict (canonical_skill_id, version) do update set
      title = excluded.title, summary = excluded.summary, content_markdown = excluded.content_markdown,
      worked_example = excluded.worked_example, tips = excluded.tips, estimated_minutes = excluded.estimated_minutes,
      active = true, metadata = excluded.metadata, updated_at = now();

    for question_data in select value from jsonb_array_elements(skill_data->'questions') loop
      content_id := (skill_data->>'code') || ':v16.2:' || (question_data->>'id');
      select bank.id into v_question_id from public.learning_question_bank bank
       where bank.source_type = 'TECESCOLA_BNCC_GUIDED_STUDY_V16_2'
         and bank.metadata->>'content_id' = content_id limit 1;

      if v_question_id is null then
        insert into public.learning_question_bank(
          package_type, source_type, source_name, subject_area, domain, topic, statement, options,
          correct_answer, explanation, difficulty, cognitive_process, context_family, knowledge_mapping_status,
          knowledge_mapping_version, estimated_minutes, provenance, source_reference, metadata, active
        ) values (
          'TECESCOLA', 'TECESCOLA_BNCC_GUIDED_STUDY_V16_2', 'TecEscola Guided Study V16.2',
          skill_data->>'area', skill_data->>'domain', lower(skill_data->>'code'), question_data->>'statement',
          question_data->'options', to_jsonb(question_data->>'answer'), question_data->>'explanation',
          question_data->>'difficulty', question_data->>'cognitiveProcess', question_data->>'contextFamily',
          'READY', 'V16.2', 2, 'TECESCOLA_BNCC_AUTHORED_V16_2', content->>'officialSourceUrl',
          jsonb_build_object('content_id', content_id, 'purpose', question_data->>'purpose',
            'official_bncc_code', skill_data->>'code', 'official_source_url', content->>'officialSourceUrl',
            'official_source_page', (skill_data->>'officialPage')::integer, 'content_pack', content->>'packVersion',
            'content_version', (content->>'contentVersion')::integer, 'content_origin', 'AUTHORED_V16_2',
            'recommended_grade', (content->>'recommendedGrade')::integer,
            'recommended_grade_source', content->>'recommendedGradeSource',
            'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING'), true
        ) returning id into v_question_id;
      else
        update public.learning_question_bank set
          subject_area = skill_data->>'area', domain = skill_data->>'domain', topic = lower(skill_data->>'code'),
          statement = question_data->>'statement', options = question_data->'options',
          correct_answer = to_jsonb(question_data->>'answer'), explanation = question_data->>'explanation',
          difficulty = question_data->>'difficulty', cognitive_process = question_data->>'cognitiveProcess',
          context_family = question_data->>'contextFamily', knowledge_mapping_status = 'READY',
          knowledge_mapping_version = 'V16.2', estimated_minutes = 2,
          provenance = 'TECESCOLA_BNCC_AUTHORED_V16_2', source_reference = content->>'officialSourceUrl',
          metadata = jsonb_build_object('content_id', content_id, 'purpose', question_data->>'purpose',
            'official_bncc_code', skill_data->>'code', 'official_source_url', content->>'officialSourceUrl',
            'official_source_page', (skill_data->>'officialPage')::integer, 'content_pack', content->>'packVersion',
            'content_version', (content->>'contentVersion')::integer, 'content_origin', 'AUTHORED_V16_2',
            'recommended_grade', (content->>'recommendedGrade')::integer,
            'recommended_grade_source', content->>'recommendedGradeSource',
            'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING'),
          active = true, updated_at = now()
         where id = v_question_id;
      end if;

      insert into public.learning_question_bank_skill_links(question_bank_id, canonical_skill_id, skill_role)
      values (v_question_id, v_skill_id, 'PRIMARY') on conflict (question_bank_id, canonical_skill_id) do nothing;

      insert into public.learning_question_sets(scope, canonical_skill_id, purpose, version, difficulty, active, metadata)
      values (
        'GLOBAL', v_skill_id, question_data->>'purpose', (content->>'contentVersion')::integer,
        question_data->>'difficulty', true,
        jsonb_build_object('content_pack', content->>'packVersion', 'content_version', (content->>'contentVersion')::integer,
          'official_bncc_code', skill_data->>'code', 'selection_policy', 'UNSEEN_FIRST_LIMIT_TWO',
          'recommended_grade', (content->>'recommendedGrade')::integer,
          'recommended_grade_source', content->>'recommendedGradeSource',
          'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING')
      ) on conflict (canonical_skill_id, purpose, version) where scope = 'GLOBAL'
      do update set difficulty = excluded.difficulty, active = true, metadata = excluded.metadata, updated_at = now()
      returning id into v_question_set_id;

      if not exists (
        select 1 from public.learning_question_set_items item
         where item.question_set_id = v_question_set_id and item.question_bank_id = v_question_id
      ) then
        select coalesce(max(position), -1) + 1 into next_position
          from public.learning_question_set_items item where item.question_set_id = v_question_set_id;
        insert into public.learning_question_set_items(question_set_id, question_bank_id, position)
        values (v_question_set_id, v_question_id, next_position);
      end if;
    end loop;

    update public.learning_curriculum_skills skill set
      metadata = coalesce(skill.metadata, '{}'::jsonb) || jsonb_build_object(
        'official_code', skill_data->>'code', 'official_source_id', 'BNCC_EM_2018',
        'official_source_url', content->>'officialSourceUrl', 'official_source_page', (skill_data->>'officialPage')::integer,
        'official_component_code', skill_data->>'componentCode',
        'official_grade_range', '1-3', 'mapping_status', 'MAPPED',
        'mapping_source', 'TECESCOLA_BNCC_GUIDED_STUDY_V16_2', 'content_pack', content->>'packVersion',
        'content_version', (content->>'contentVersion')::integer, 'content_origin', 'AUTHORED_V16_2',
        'recommended_grade', (content->>'recommendedGrade')::integer,
        'recommended_grade_source', content->>'recommendedGradeSource',
        'sequence_after', skill_data->>'sequenceAfter',
        'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING'
      ),
      subject_area = skill_data->>'area', domain = skill_data->>'domain', title = skill_data->>'title',
      description = skill_data->>'officialDescription', stage = 'ENSINO_MEDIO', grade_level = null,
      active = true, node_kind = 'LEAF', content_readiness = 'CONTENT_READY', mastery_targetable = false,
      bncc_alignment_status = 'MAPPED', publication_status = 'STAGING',
      pedagogical_review_status = 'PEDAGOGICAL_REVIEW_PENDING', updated_at = now()
     where skill.id = v_skill_id;

    select private.validate_mapped_bncc_skill_v12(v_skill_id, skill_data->>'code', skill.metadata)
      into validation from public.learning_curriculum_skills skill where skill.id = v_skill_id;
    if validation->>'status' <> 'READY' then
      raise exception 'GUIDED_STUDY_V16_2_SKILL_VALIDATION_FAILED code=% result=%', skill_data->>'code', validation;
    end if;
  end loop;

  if not exists (
    select 1 from public.learning_adaptive_content_packs pack
     where pack.pack_version = content->>'packVersion' and pack.active
       and pack.publication_status = 'PUBLISHED' and pack.technical_validation_status = 'PUBLISHED'
       and pack.pedagogical_review_status = 'PEDAGOGICAL_REVIEW_PENDING'
  ) then raise exception 'GUIDED_STUDY_V16_2_PACK_VALIDATION_FAILED'; end if;

  if exists (
    select 1 from jsonb_array_elements(content->'skills') entry
    join public.learning_curriculum_skills skill on skill.code = entry->>'code' and skill.catalog_id = v_catalog_id
    where skill.publication_status <> 'PUBLISHED' or skill.technical_validation_status <> 'PUBLISHED'
       or skill.content_readiness <> 'ADAPTIVE_READY' or not skill.mastery_targetable
       or skill.pedagogical_review_status <> 'PEDAGOGICAL_REVIEW_PENDING'
  ) then raise exception 'GUIDED_STUDY_V16_2_SKILL_PUBLICATION_GATE_FAILED'; end if;
end;
$guided_study_v16_2_content_seed$;

notify pgrst, 'reload schema';
commit;
